# ---------- Glossar (AEO: Erklaerungen + FAQ-Schema) ----------
GLOSSAR=[
dict(slug='was-ist-der-dax',term='Was ist der DAX?',short='Der wichtigste deutsche Aktienindex im Überblick.',body='<p>Der DAX (Deutscher Aktienindex) bündelt die 40 größten und umsatzstärksten börsennotierten Unternehmen Deutschlands. Er wird von der Börse Frankfurt berechnet und gilt als zentrales Barometer für die deutsche Wirtschaft. Der Index existiert seit 1988 und wurde im September 2021 von 30 auf 40 Werte erweitert.</p><p>Der DAX ist ein sogenannter Performanceindex: Dividenden der enthaltenen Unternehmen werden rechnerisch reinvestiert. Steigt oder fällt der DAX, heißt das also nicht automatisch, dass alle 40 Einzelwerte sich gleich bewegen - es handelt sich um einen gewichteten Durchschnitt, in dem große Unternehmen stärker zählen.</p>',faq=[dict(q='Wie viele Unternehmen sind im DAX?',a='Seit September 2021 sind es 40 Unternehmen. Davor waren es 30.'),dict(q='Wo wird der DAX berechnet?',a='Von der Börse Frankfurt. Die Berechnung läuft an Handelstagen fortlaufend.'),dict(q='Ist der DAX eine Kaufempfehlung?',a='Nein. Der DAX ist ein reiner Marktindikator. Ob und wie man in ihn investiert, ist eine individuelle Entscheidung - diese Seite gibt dazu keine Empfehlung.')]),
dict(slug='was-ist-ein-etf',term='Was ist ein ETF?',short='Börsengehandelte Indexfonds einfach erklärt.',body='<p>Ein ETF (Exchange Traded Fund) ist ein börsengehandelter Fonds, der meist einen Index wie den DAX oder den S&P 500 nachbildet. Statt einzelne Aktien zu kaufen, erwirbt man mit einem ETF anteilig einen ganzen Korb von Werten - das streut das Risiko breiter als eine Einzelaktie.</p><p>ETFs werden an der Börse gehandelt und haben in der Regel niedrige laufende Kosten (die sogenannte Gesamtkostenquote, englisch TER). Auch bei ETFs gilt: Kurse schwanken, Verluste bis hin zum Totalverlust sind möglich, und die Wertentwicklung der Vergangenheit sagt nichts über die Zukunft.</p>',faq=[dict(q='Was kostet ein ETF?',a='Die laufenden Kosten (TER) vieler Index-ETFs liegen im Bereich von etwa 0,05 bis 0,5 Prozent pro Jahr, je nach Produkt.'),dict(q='Ist ein ETF sicher?',a='Nein. Ein ETF streut das Risiko breiter als eine Einzelaktie, bleibt aber ein Investment mit Schwankungs- und Verlustrisiko.')]),
dict(slug='was-ist-eine-aktie',term='Was ist eine Aktie?',short='Unternehmensanteile an der Börse verstehen.',body='<p>Eine Aktie ist ein Anteil an einem Unternehmen. Wer eine Aktie kauft, wird Miteigentümer und partizipiert an der Entwicklung des Unternehmens - an Kursgewinnen wie an Kursverlusten. Je nach Aktiengesellschaft kann ein Stimmrecht auf der Hauptversammlung dazukommen.</p><p>Der Kurs einer Aktie entsteht durch Angebot und Nachfrage an der Börse und kann stark schwanken. Deshalb gilt an der Börse der Grundsatz: nur Geld einsetzen, dessen Verlust man verkraften kann.</p>',faq=[dict(q='Was bedeutet der Aktienkurs?',a='Der Preis, zu dem eine Aktie zuletzt an der Börse gehandelt wurde. Er ändert sich fortlaufend mit Angebot und Nachfrage.'),dict(q='Bekomme ich als Aktionär Geld vom Unternehmen?',a='Nur wenn das Unternehmen eine Dividende ausschüttet - das ist freiwillig und nicht garantiert.')]),
dict(slug='was-ist-eine-dividende',term='Was ist eine Dividende?',short='Gewinnbeteiligung für Aktionäre erklärt.',body='<p>Eine Dividende ist eine Gewinnausschüttung: Ein Unternehmen gibt einen Teil seines Gewinns an seine Aktionäre weiter. In Deutschland wird die Dividende üblicherweise einmal pro Jahr nach der Hauptversammlung ausgezahlt, in den USA oft vierteljährlich.</p><p>Wichtig: Eine Dividende ist keine Garantie. Unternehmen können sie kürzen oder streichen, etwa in schwierigen Jahren. Eine hohe Dividendenrendite allein sagt nichts darüber, ob eine Aktie eine gute Anlage ist.</p>',faq=[dict(q='Muss jedes Unternehmen eine Dividende zahlen?',a='Nein. Die Ausschüttung ist freiwillig und wird von der Hauptversammlung beschlossen.'),dict(q='Was ist die Dividendenrendite?',a='Die Jahresdividende geteilt durch den aktuellen Aktienkurs, in Prozent.')]),
dict(slug='was-bedeutet-volatilitaet',term='Was bedeutet Volatilität?',short='Warum Kurse schwanken und was das bedeutet.',body='<p>Volatilität beschreibt, wie stark der Kurs eines Wertpapiers oder Index um seinen Durchschnitt schwankt. Hohe Volatilität bedeutet große Ausschläge in beide Richtungen - Chancen wie Risiken nehmen zu. Niedrige Volatilität steht für ruhigere Kursbewegungen.</p><p>Für Einsteiger ist vor allem eines wichtig: Phasen hoher Volatilität, etwa rund um Zinsentscheide oder Unternehmenszahlen, führen häufig zu hektischen Reaktionen am Markt. Das ist normal und kein Qualitätsurteil über ein Unternehmen.</p>',faq=[dict(q='Ist hohe Volatilität schlecht?',a='Nicht per se. Sie bedeutet nur stärkere Schwankungen in beide Richtungen.'),dict(q='Woran misst man Volatilität?',a='Üblicherweise an der Standardabweichung der Kursrenditen über einen Zeitraum.')]),
dict(slug='was-ist-ein-wechselkurs',term='Was ist ein Wechselkurs?',short='EUR/USD und Co. verstehen.',body='<p>Ein Wechselkurs gibt an, wie viel eine Währung in einer anderen wert ist - zum Beispiel, wie viele US-Dollar man für einen Euro bekommt (EUR/USD). Wechselkurse entstehen am Devisenmarkt und verändern sich fortlaufend.</p><p>Als neutrale Referenz veröffentlicht die Europäische Zentralbank an jedem TARGET-Handelstag gegen 16:00 Uhr ihre Euro-Referenzkurse. Sie dienen der Information und sind nicht zwingend die Kurse, zu denen Banken tatsächlich tauschen.</p>',faq=[dict(q='Woher kommen die Wechselkurse auf dieser Seite?',a='Von der Europäischen Zentralbank (Euro-Referenzkurse) beziehungsweise von den genannten Marktdatenquellen.'),dict(q='Warum weicht der Kurs meiner Bank ab?',a='Banken und Wechselstuben schlagen Auf- und Abschläge auf den Marktkurs.')]),
]
